def transform(grid):
    """Mark a truncated horizontal color run's missing rightward continuation."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    # Compare horizontal runs of each foreground color. A shorter run with
    # the same (or immediately adjacent) left edge as a longer run indicates
    # a truncated copy; mark its missing right-hand portion with 1.
    for r, row in enumerate(grid):
        for color in set(row) - {bg}:
            positions = [c for c, v in enumerate(row) if v == color]
            if not positions:
                continue
            # Use the first contiguous run, rather than spanning intervening
            # background/color pixels.
            start = positions[0]
            end = start
            while end + 1 < w and row[end + 1] == color:
                end += 1
            for rr, other in enumerate(grid):
                if rr == r:
                    continue
                # Find a solid run of this color on the comparison row.
                for c in range(max(0, start - 1), min(w, start + 2)):
                    if other[c] != color:
                        continue
                    e = c
                    while e + 1 < w and other[e + 1] == color:
                        e += 1
                    if e > end and c <= start and end + 1 <= w:
                        for x in range(end + 1, e + 1):
                            if row[x] == bg:
                                out[r][x] = 1
    return out
